1	export type QuoteResult = { premium: number };
2	
3	export type ScenarioResults = { results: QuoteResult[] };
4	
5	const PROCESSING_FEE = 5;
6	
7	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
8	
9	const ITEM_BASE_PREMIUM: Record<string, number> = {
10	  sword: 100,
11	  amulet: 60,
12	  staff: 80,
13	  potion: 40,
14	  rune: 25,
15	};
16	
17	type Item = { type: string };
18	
19	type Step = { op: string; items: Item[] };
20	
21	type Scenario = { customer: { yearsWithMHPCO: number }; steps: Step[] };
22	
23	const COMPONENT_BLOCK_SIZE = 3;
24	
25	const COMPONENT_BLOCK_BASE_PREMIUM = 60;
26	
27	const policyBasePremium = (items: Item[]): number => {
28	  const runes = items.filter((item) => item.type === "rune");
29	  if (runes.length === COMPONENT_BLOCK_SIZE) return COMPONENT_BLOCK_BASE_PREMIUM;
30	
31	  return items.reduce((sum, item) => sum + ITEM_BASE_PREMIUM[item.type], 0);
32	};
33	
34	const quoteStep = (step: Step): QuoteResult => {
35	  const basePremium = policyBasePremium(step.items);
36	  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
37	  return {
38	    premium: basePremium + firstInsuranceSurcharge + PROCESSING_FEE,
39	  };
40	};
41	
42	export const runScenario = (scenario: Scenario): ScenarioResults => ({
43	  results: scenario.steps.map(quoteStep),
44	});
