const COMPONENT_BLOCK_SIZE = 3;

// Only forced so far by a policy consisting of exactly one rune block, so this
// is the premium of the whole policy rather than of a single block.
const ALL_ONE_COMPONENT_BLOCK_BASE_PREMIUM = 60;

const policyBasePremium = (items: Item[]): number => {
  const components = items.filter((item) => item.type === "rune");
  if (components.length === COMPONENT_BLOCK_SIZE)
    return ALL_ONE_COMPONENT_BLOCK_BASE_PREMIUM;

  return items.reduce((sum, item) => sum + ITEM_BASE_PREMIUM[item.type], 0);
};
